import React, { useState } from 'react';
import Navbar from './components/Navbar';
import TopBar from './components/TopBar';
import './styles/navbar.css';

const App = () => {
  const [heading, setHeading] = useState('Sheet Rule'); // Default heading

  const handleBack = () => {
    console.log('Back button clicked');
  };

  const handleClose = () => {
    console.log('Close button clicked');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column' }}>
      <TopBar heading={heading} onBack={handleBack} onClose={handleClose} />
      <div style={{ display: 'flex', flex: 1 }}>
        <Navbar setHeading={setHeading} />
        <div style={{ flex: 1 }}>
          <h1>Hello!</h1>
          <p>Welcome to STA-UI 🚀</p>
          <p>This is a simple React application to demonstrate the use of components.</p>
        </div>
      </div>
    </div>
  );
};

export default App;
